#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_new_with_string_basic_string_copy(void) {
    // Setup: create a test string
    char test_str[] = "hello world";

    // Test: call buffer_new_with_string
    buffer_t *buf = buffer_new_with_string(test_str);

    // Assertions
    TEST_ASSERT_NOT_NULL(buf);
    helper_assert_buffer_string_equals(buf, "hello world");
    helper_assert_buffer_length(buf, 11); // strlen("hello world") == 11

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_new_with_string_basic_string_copy);
    return UNITY_END();
}


